        self.assert_error(self.evaluate("missing-output"), "invalid-envelope")
        self.assert_error(self.evaluate("bad-envelope"), "invalid-envelope")

"""Deterministic response gates. Failed data never reaches policy routing."""

import json
import re
from datetime import date
from pathlib import Path
from typing import Any

SCHEMA = json.loads((Path(__file__).resolve().parents[1] / "snapshot.schema.json").read_text())
SCALAR_FIELDS = tuple(name for name in SCHEMA["required"] if name not in ("issues", "supporting_quotes"))


class ExtractionError(ValueError):
    def __init__(self, code: str, message: str):
        super().__init__(message)
        self.code = code


def error_record(code: str, diagnostic: str, response_source: str = "unknown") -> dict[str, Any]:
    return {
        "extraction": None, "status": "error", "owner": "IT Service Desk",
        "next_action": "retry-extraction", "error": {"code": code, "message": diagnostic},
        "response_source": response_source,
    }


def _invalid(message: str) -> None:
    raise ExtractionError("invalid-extraction", message)


def _object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("Duplicate JSON property")
        result[key] = value
    return result


def _constant(value):
    raise ValueError("Non-finite JSON number")


def validate_response(envelope: Any, message: str) -> dict[str, Any]:
    if not isinstance(envelope, dict):
        raise ExtractionError("invalid-envelope", "Provider response must be an envelope object")
    if envelope.get("refusal"):
        raise ExtractionError("refusal", "Provider refused extraction; inspect the message before retrying")
    status = envelope.get("status")
    if status == "incomplete":
        raise ExtractionError("incomplete", "Provider response was incomplete; retry extraction")
    if status != "completed" or not isinstance(envelope.get("output_text"), str):
        raise ExtractionError("invalid-envelope", "Expected completed status and string output_text")
    try:
        extraction = json.loads(envelope["output_text"], object_pairs_hook=_object, parse_constant=_constant)
    except (ValueError, RecursionError) as error:
        raise ExtractionError("invalid-json", "Provider output is not valid JSON; retry extraction") from error
    if not isinstance(extraction, dict):
        _invalid("Extraction must be a JSON object")
    if set(extraction) != set(SCHEMA["required"]):
        _invalid("Extraction must contain exactly the 14 schema properties")
    for field, specification in SCHEMA["properties"].items():
        value = extraction[field]
        if field in ("supporting_quotes", "issues"):
            if not isinstance(value, list) or any(not isinstance(item, str) for item in value):
                _invalid(f"{field} must be an array of strings")
        else:
            if value is not None and (not isinstance(value, str) or not value.strip()):
                _invalid(f"{field} must be a nonempty string or null")
            if "enum" in specification and value not in specification["enum"]:
                _invalid(f"{field} is outside the schema enum")
            if value is not None and field in ("request_date", "start_date", "end_date"):
                try:
                    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
                        raise ValueError("Not ISO date")
                    date.fromisoformat(value)
                except ValueError:
                    _invalid(f"{field} must be a real YYYY-MM-DD calendar date")
    issue_text = " ".join(extraction["issues"]).lower().replace("_", " ")
    for field in SCALAR_FIELDS:
        if extraction[field] is None and field.replace("_", " ") not in issue_text:
            _invalid(f"Null {field} requires a field-specific issue")
    for quote in extraction["supporting_quotes"]:
        if not quote or quote not in message:
            _invalid("Each supporting quote must be a nonempty exact source substring")
    return extraction


def evaluate_response(envelope: Any, message: str) -> dict[str, Any]:
    """Return validated facts or a structured error; successful facts await routing."""
    source = envelope.get("response_source", "mock") if isinstance(envelope, dict) else "unknown"
    try:
        extraction = validate_response(envelope, message)
    except ExtractionError as error:
        return error_record(error.code, str(error), source)
    return {"extraction": extraction, "error": None, "response_source": source}

"""Service-level composition of source loading, validation and review routing."""

from pathlib import Path
from typing import Any, Iterable

from .inputs import process_exports
from .policy import route
from .providers import Provider
from .validation import error_record, evaluate_response


def record_response(document_id: str, source_sha256: str, message: str, envelope: Any) -> dict[str, Any]:
    result = evaluate_response(envelope, message)
    if result["error"] is None:
        result.update(route(result["extraction"], message, document_id))
    return {"document_id": document_id, "source_sha256": source_sha256, **result}


def process_documents(paths: Iterable[Path], *, provider: Provider) -> list[dict[str, Any]]:
    results = []
    for loaded in process_exports(paths, provider=provider):
        if loaded.error:
            result = {"document_id": loaded.document_id, "source_sha256": loaded.source_sha256,
                      **error_record(loaded.error["code"], loaded.error["message"], "not-called")}
        else:
            result = record_response(loaded.document_id, loaded.source_sha256, loaded.message, loaded.response)
        results.append(result)
    return results

"""Ordered human-review policy and independent source override inspection."""

import copy
import re
from pathlib import Path
from typing import Any

from .validation import SCALAR_FIELDS

POLICY_VERSION = "northstar-v1"
_OVERRIDE = re.compile(
    r"system\s+override|bypass\s+approval|ignore\s+(?:all\s+)?(?:previous|prior|system)\s+instructions"
    r"|(?:display|disclose|reveal|print|show)\b[^.\n]{0,60}\b(?:api[ _-]?key|credentials|secrets)"
    r"|mark\b[^.\n]{0,40}\bapproved|highest[- ]priority\s+system\s+instruction",
    re.IGNORECASE,
)


def route(extraction: dict[str, Any], message: str, document_id: str) -> dict[str, Any]:
    """Accept validated facts only. Source inspection is conservative, not exhaustive."""
    facts = copy.deepcopy(extraction)
    issues = facts["issues"]
    source_override = bool(_OVERRIDE.search(message))
    reported_override = any(re.search(r"override|prompt injection|bypass approval", issue, re.I) for issue in issues)
    if source_override or reported_override:
        if source_override:
            if not any("override" in issue.lower() for issue in issues):
                issues.append("Instruction override attempt detected in source; requires human inspection")
            if message not in facts["supporting_quotes"]:
                facts["supporting_quotes"].append(message)
        decision = ("review", "IT Service Desk", "inspect-message")
    elif facts["kind"] == "withdrawal" and facts["request_id"] and facts["request_date"]:
        decision = ("review", "IT Service Desk", "confirm-withdrawal")
    else:
        if facts["request_id"] and facts["request_id"] != Path(document_id).stem:
            issues.append(f"request_id {facts['request_id']} differs from document_id {document_id}")
        if facts["start_date"] and facts["end_date"] and facts["start_date"] > facts["end_date"]:
            issues.append("start_date is after end_date; clarify the access window")
        if facts["kind"] not in ("new", "change") or any(facts[field] is None for field in SCALAR_FIELDS) or issues:
            decision = ("needs-information", "IT Service Desk", "clarify")
        elif facts["environment"] == "production" or facts["permission"] in ("write", "admin"):
            decision = ("review", "Security Review", "review-risk-then-owner")
        else:
            decision = ("review", "System Owner", "review-request")
    return {"extraction": facts, **dict(zip(("status", "owner", "next_action"), decision))}

"""Configurable chat-completions adapter; transport is injectable for offline use."""

import json
import math
import os
from dataclasses import dataclass
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime
from typing import Any, Callable, Mapping
from urllib.error import HTTPError, URLError
from urllib.parse import urlsplit
from urllib.request import HTTPRedirectHandler, Request, build_opener

from .prompt import SYSTEM_PROMPT, build_messages
from .providers import ProviderUnavailable
from .validation import SCHEMA


class ProviderFailure(ProviderUnavailable):
    def __init__(self, code: str, diagnostic: str, *, retryable: bool = False, retry_after: float | None = None):
        super().__init__(diagnostic)
        self.code = code
        self.retryable = retryable
        self.retry_after = retry_after


@dataclass(frozen=True)
class HttpConfig:
    endpoint: str
    model: str
    provider: str = "openai-compatible"
    temperature: float = 0
    max_completion_tokens: int = 2048
    timeout: float = 60
    max_response_bytes: int = 1_048_576

    def __post_init__(self):
        parsed = urlsplit(self.endpoint)
        if parsed.scheme != "https" or not parsed.hostname or parsed.username or parsed.password or parsed.query or parsed.fragment:
            raise ValueError("MODEL_ENDPOINT must be an HTTPS URL without credentials, query or fragment")
        if not self.model or not self.provider:
            raise ValueError("A provider and model ID are required")
        if not math.isfinite(self.timeout) or self.timeout <= 0 or self.max_response_bytes <= 0 or self.max_completion_tokens <= 0:
            raise ValueError("Timeout and response/token limits must be positive")
        if not math.isfinite(self.temperature) or not 0 <= self.temperature <= 2:
            raise ValueError("Temperature must be between 0 and 2")


@dataclass(frozen=True)
class HttpReply:
    status: int
    headers: Mapping[str, str]
    body: bytes


class _NoRedirect(HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def http_transport(*, endpoint: str, headers: dict, body: bytes, timeout: float, max_response_bytes: int) -> HttpReply:
    request = Request(endpoint, data=body, headers=headers, method="POST")
    opener = build_opener(_NoRedirect())
    try:
        response = opener.open(request, timeout=timeout)
    except HTTPError as error:
        response = error
    with response:
        data = response.read(max_response_bytes + 1)
        if len(data) > max_response_bytes:
            raise ProviderFailure("response-too-large", "Provider response exceeded configured size limit")
        return HttpReply(response.code, dict(response.headers.items()), data)


def _retry_after(headers: Mapping[str, str]) -> float | None:
    value = next((v for k, v in headers.items() if k.lower() == "retry-after"), None)
    if value is None:
        return None
    try:
        seconds = float(value)
    except ValueError:
        try:
            seconds = (parsedate_to_datetime(value) - datetime.now(timezone.utc)).total_seconds()
        except (ValueError, TypeError, OverflowError):
            return None
    return max(0, seconds) if math.isfinite(seconds) else None


class HttpProvider:
    def __init__(self, config: HttpConfig, *, credential: str, transport: Callable = http_transport,
                 prompt: str = SYSTEM_PROMPT, schema: dict | None = None):
        if not credential:
            raise ValueError("API_KEY is required for live mode")
        self.config = config
        self._credential = credential
        self.transport = transport
        self.prompt = prompt
        self.schema = SCHEMA if schema is None else schema
        self.response_source = f"{config.provider}/{config.model}"

    @classmethod
    def from_environment(cls, *, environment: Mapping[str, str] | None = None, transport: Callable = http_transport):
        env = os.environ if environment is None else environment
        if not env.get("MODEL_ENDPOINT") or not env.get("MODEL_ID"):
            raise ValueError("Live mode requires MODEL_ENDPOINT and MODEL_ID")
        config = HttpConfig(
            endpoint=env["MODEL_ENDPOINT"], model=env["MODEL_ID"],
            provider=env.get("MODEL_PROVIDER", "openai-compatible"),
            temperature=float(env.get("MODEL_TEMPERATURE", "0")),
            max_completion_tokens=int(env.get("MODEL_MAX_COMPLETION_TOKENS", "2048")),
            timeout=float(env.get("MODEL_TIMEOUT_SECONDS", "60")),
            max_response_bytes=int(env.get("MODEL_MAX_RESPONSE_BYTES", "1048576")),
        )
        return cls(config, credential=env.get("API_KEY", ""), transport=transport)

    def request_body(self, message: str) -> dict[str, Any]:
        return {
            "model": self.config.model, "messages": build_messages(message, self.prompt),
            "temperature": self.config.temperature, "max_completion_tokens": self.config.max_completion_tokens,
            "stream": False, "response_format": {"type": "json_schema", "json_schema": {
                "name": "access_request", "strict": True, "schema": self.schema}},
        }

    def request_evidence(self, message: str) -> dict[str, Any]:
        return {
            "request": {"method": "POST", "endpoint": self.config.endpoint,
                        "headers": {"Content-Type": "application/json", "Authorization": "[REDACTED]"},
                        "body": self.request_body(message)},
            "response_handling": ["HTTP status classification", "bounded UTF-8 JSON envelope",
                                  "refusal before content", "finish_reason must be stop",
                                  "local schema/date/quote validation before routing"],
        }

    def extract(self, message: str) -> dict[str, Any]:
        try:
            reply = self.transport(
                endpoint=self.config.endpoint,
                headers={"Content-Type": "application/json", "Authorization": f"Bearer {self._credential}"},
                body=json.dumps(self.request_body(message)).encode("utf-8"),
                timeout=self.config.timeout, max_response_bytes=self.config.max_response_bytes,
            )
        except ProviderFailure:
            raise
        except (ProviderUnavailable, OSError, URLError, TimeoutError):
            # Never retain the original exception text or credential-bearing request.
            raise ProviderFailure("provider-unavailable", "Provider transport unavailable; retry extraction", retryable=True) from None
        if reply.status != 200:
            raise ProviderFailure(f"http-{reply.status}", f"Provider returned HTTP {reply.status}; inspect configuration or retry",
                                  retryable=reply.status == 429 or 500 <= reply.status <= 599,
                                  retry_after=_retry_after(reply.headers))
        if len(reply.body) > self.config.max_response_bytes:
            raise ProviderFailure("response-too-large", "Provider response exceeded configured size limit")
        try:
            # Redact an echoed credential before any output can reach state/logs.
            data = json.loads(reply.body.decode("utf-8").replace(self._credential, "[REDACTED]"))
            choices = data["choices"]
            if not isinstance(choices, list) or len(choices) != 1:
                raise ValueError("Expected one choice")
            choice = choices[0]
            response = choice["message"]
            if not isinstance(response, dict) or "finish_reason" not in choice:
                raise ValueError("Invalid completion envelope")
            refusal = response.get("refusal")
            content = response.get("content")
            reason = choice["finish_reason"]
            if not refusal and reason == "stop" and not isinstance(content, str):
                raise ValueError("Missing content")
            actual_model = data.get("model", self.config.model)
            if not isinstance(actual_model, str) or not actual_model:
                raise ValueError("Invalid model ID")
        except (ValueError, KeyError, TypeError, IndexError, RecursionError):
            raise ProviderFailure("invalid-envelope", "Provider returned an invalid chat-completions envelope") from None
        return {"status": "completed" if reason == "stop" else "incomplete", "refusal": refusal,
                "output_text": content, "response_source": f"{self.config.provider}/{actual_model}"}

"""JSON operator CLI for intake, inspection, recovery and immutable exports."""

import argparse
import json
import sys
from dataclasses import replace
from pathlib import Path

from .inputs import batch_paths
from .mock_config import provider_for_settings, settings_for_source
from .repository import ProcessingSettings, Repository
from .scheduler import Scheduler


def _parser():
    parser = argparse.ArgumentParser(prog="python3 -m access_intake")
    commands = parser.add_subparsers(dest="command", required=True)
    for name in ("intake", "queue", "progress", "history", "retry", "resume", "refresh", "export"):
        command = commands.add_parser(name)
        command.add_argument("--state", type=Path, required=True)
        if name in ("intake", "refresh"):
            command.add_argument("--provider", choices=("mock", "live"), default="mock")
            command.add_argument("--mock-map", type=Path)
            command.add_argument("--policy-version")
            command.add_argument("--prompt-file", type=Path)
        if name == "intake":
            command.add_argument("paths", nargs="+", type=Path)
        if name in ("intake", "retry", "resume", "refresh"):
            command.add_argument("--workers", type=int, default=4)
            command.add_argument("--timeout", type=float, default=60)
            command.add_argument("--max-calls", type=int, default=3)
            command.add_argument("--enqueue-only", action="store_true")
        if name in ("queue", "progress", "history"):
            command.add_argument("--limit", type=int, default=100)
            command.add_argument("--offset", type=int, default=0)
        if name == "history":
            command.add_argument("--document", required=True)
        if name == "retry":
            command.add_argument("--attempt", required=True)
        if name == "export":
            command.add_argument("--out", type=Path, required=True)
            command.add_argument("--copy-to", type=Path)
    return parser


def _settings(args):
    if args.provider == "live":
        from .http_provider import HttpProvider
        settings = ProcessingSettings.from_provider(HttpProvider.from_environment())
    else:
        settings = ProcessingSettings()
    if args.policy_version:
        settings = replace(settings, policy_version=args.policy_version)
    if args.prompt_file:
        settings = replace(settings, prompt=args.prompt_file.read_text(encoding="utf-8"))
    return settings


def main(argv=None, *, provider_factory=None, hook=None, scheduler_options=None):
    args = _parser().parse_args(argv)
    try:
        if hasattr(args, "limit") and (not 1 <= args.limit <= 10000 or args.offset < 0):
            raise ValueError("Use a limit from 1 to 10000 and a nonnegative offset")
        with Repository(args.state) as repo:
            if args.command == "queue":
                result = repo.queue_page(limit=args.limit, offset=args.offset)
            elif args.command == "progress":
                result = repo.progress_page(limit=args.limit, offset=args.offset)
            elif args.command == "history":
                records = repo.history(args.document)
                result = {"total": len(records), "items": records[args.offset:args.offset + args.limit]}
            elif args.command == "export":
                from .snapshots import export_generation, read_snapshot
                manifest = export_generation(repo, args.out)
                if args.copy_to:
                    snapshot = read_snapshot(args.out)
                    args.copy_to.mkdir(parents=True, exist_ok=True)
                    # Copy only the generation resolved and verified above.
                    (args.copy_to / "extractions.jsonl").write_text("".join(json.dumps(r, ensure_ascii=False) + "\n" for r in snapshot["extractions"]), encoding="utf-8")
                    (args.copy_to / "queue.json").write_text(json.dumps(snapshot["queue"], ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
                result = manifest
            else:
                if args.command == "intake":
                    paths = batch_paths(p for path in args.paths for p in (sorted(path.glob("*.json")) if path.is_dir() else [path]))
                    settings = _settings(args)
                    for path in paths:
                        raw = path.read_bytes()
                        producing = settings_for_source(path, raw, args.mock_map or Path("config/mock-map.json"), settings) if args.provider == "mock" else settings
                        repo._schedule(path.name, raw, producing)
                elif args.command == "retry":
                    repo.enqueue_retry(args.attempt)
                elif args.command == "refresh":
                    settings = _settings(args)
                    rows = repo.connection.execute("SELECT a.* FROM documents d JOIN attempts a ON a.attempt_id=d.latest_attempt_id").fetchall()
                    for row in rows:
                        producing = settings
                        if args.provider == "mock":
                            producing = (settings_for_source(row["document_id"], row["source_bytes"], args.mock_map, settings)
                                         if args.mock_map else replace(settings, request_settings=json.loads(row["settings_json"])["request_settings"]))
                        repo._schedule(row["document_id"], row["source_bytes"], producing)
                metrics = {} if args.enqueue_only else Scheduler(repo, provider_factory=provider_factory or provider_for_settings,
                    workers=args.workers, timeout=args.timeout, max_calls=args.max_calls, hook=hook,
                    **(scheduler_options or {})).run()
                result = {"scheduler": metrics, "progress": repo.progress_page(limit=20)}
        print(json.dumps(result, ensure_ascii=False))
        return 0
    except KeyboardInterrupt:
        return 130
    except (ValueError, OSError, KeyError) as error:
        print(json.dumps({"error": str(error)}), file=sys.stderr)
        return 2

"""Explicit saved-response configuration for reproducible offline CLI runs."""

import hashlib
import json
from dataclasses import replace
from pathlib import Path

from .inputs import InputError, decode_export
from .providers import ProviderUnavailable


def settings_for_source(path, raw, manifest_path, settings):
    try:
        document = decode_export(Path(path), raw)
    except InputError:
        return settings
    manifest_path = Path(manifest_path)
    manifest = json.loads(manifest_path.read_text())
    identity = hashlib.sha256(document.message.encode("utf-8")).hexdigest()
    entry = manifest.get(identity)
    if entry is None:
        return replace(settings, request_settings={})
    fixture = (manifest_path.parent / entry["response"]).resolve()
    configuration = {"path": str(fixture), "sha256": hashlib.sha256(fixture.read_bytes()).hexdigest(),
                     "substitutions": entry.get("substitutions", {})}
    return replace(settings, request_settings={"mock_response": configuration})


class SavedProvider:
    def __init__(self, settings):
        self.settings = settings

    def extract(self, message):
        entry = self.settings.request_settings.get("mock_response")
        if entry is None:
            raise ProviderUnavailable("No saved response configured for this message")
        raw = Path(entry["path"]).read_bytes()
        if hashlib.sha256(raw).hexdigest() != entry["sha256"]:
            raise ProviderUnavailable("Saved response changed; refresh the producing configuration")
        text = raw.decode("utf-8")
        for old, new in entry["substitutions"].items():
            text = text.replace(old, new)
        envelope = json.loads(text)
        return {**envelope, "response_source": "mock"}


def provider_for_settings(settings):
    if settings.provider == "mock":
        return SavedProvider(settings)
    from .http_provider import HttpProvider
    return HttpProvider.from_settings(settings)

"""Bounded process workers, durable backoff and hard total-attempt deadlines."""

import json
import multiprocessing
import random
import signal
import threading
from multiprocessing.connection import wait as wait_connections
from time import sleep, time

from .providers import ProviderUnavailable
from .repository import ProcessingSettings, Repository
from .validation import error_record

CTX = multiprocessing.get_context("fork")


def retry_delay(error, calls, *, jitter=random.random, base_delay=0.5):
    requested = getattr(error, "retry_after", None)
    if requested is not None:
        return min(60, max(0, requested))
    return min(10, base_delay * 2 ** (calls - 1)) * (1 + jitter() * 0.25)


def _compute(path, job, provider, sender):
    signal.signal(signal.SIGTERM, signal.SIG_DFL)
    try:
        with Repository(path) as repository:
            result = repository.compute(job, provider=provider, raise_provider_errors=True)
        sender.send(("result", result))
    except (ProviderUnavailable, TimeoutError) as error:
        sender.send(("failure", {"code": getattr(error, "code", "provider-unavailable"),
                                 "retryable": getattr(error, "retryable", True),
                                 "retry_after": getattr(error, "retry_after", None)}))
    except BaseException:
        sender.send(("failure", {"code": "worker-error", "retryable": False, "retry_after": None}))
    finally:
        sender.close()


class Scheduler:
    def __init__(self, repository, *, provider_factory, workers=4, timeout=60, max_calls=3,
                 clock=time, wait=sleep, jitter=random.random, base_delay=0.5, hook=None):
        if not 1 <= workers <= 32 or timeout <= 0 or not 1 <= max_calls <= 3:
            raise ValueError("Use 1–32 workers, a positive timeout, and 1–3 provider calls")
        self.repository = repository
        self.factory = provider_factory
        self.workers, self.timeout, self.max_calls = workers, timeout, max_calls
        self.clock, self.wait, self.jitter = clock, wait, jitter
        self.base_delay = base_delay
        self.hook = hook or (lambda stage, job: None)

    def _failure(self, job, details):
        from .http_provider import ProviderFailure
        error = ProviderFailure(details["code"], "Provider call failed", retryable=details["retryable"], retry_after=details.get("retry_after"))
        delay = retry_delay(error, job["call_count"], jitter=self.jitter, base_delay=self.base_delay)
        if error.retryable and job["call_count"] < self.max_calls and self.clock() + delay < job["deadline"]:
            self.repository.defer(job, seconds=delay)
            self.hook("retry-wait", job)
            return
        settings = ProcessingSettings(**json.loads(job["settings_json"]))
        source = "mock" if settings.provider == "mock" else f"{settings.provider}/{settings.model}"
        result = self.repository.decorate(job, error_record(error.code, "Extraction failed or timed out; retry this saved attempt", source))
        self.repository.finish(job, result)
        self.hook("completed", job)

    def run(self):
        self.repository.recover()
        active = {}
        metrics = {"max_active": 0, "calls": 0}
        old_handler = None
        if threading.current_thread() is threading.main_thread():
            old_handler = signal.getsignal(signal.SIGTERM)
            def interrupted(signum, frame):
                raise KeyboardInterrupt
            signal.signal(signal.SIGTERM, interrupted)
        try:
            while True:
                while len(active) < self.workers:
                    job = self.repository.claim(lease_seconds=self.timeout + 5)
                    if job is None:
                        break
                    job = self.repository.prepare_call(job, timeout=self.timeout)
                    if self.clock() >= job["deadline"]:
                        self._failure(job, {"code": "attempt-timeout", "retryable": False})
                        continue
                    try:
                        provider = self.factory(ProcessingSettings(**json.loads(job["settings_json"])))
                    except (ValueError, OSError, KeyError, ProviderUnavailable):
                        self._failure(job, {"code": "provider-configuration", "retryable": False})
                        continue
                    receiver, sender = CTX.Pipe(duplex=False)
                    process = CTX.Process(target=_compute, args=(self.repository.path, job, provider, sender))
                    process.start()
                    sender.close()
                    active[receiver] = (process, job)
                    metrics["calls"] += 1
                    metrics["max_active"] = max(metrics["max_active"], len(active))
                    self.hook("spawned", job)
                if not active:
                    next_run = self.repository.connection.execute("SELECT min(next_run_at) FROM attempts WHERE work_state IN ('queued','retry-wait')").fetchone()[0]
                    if next_run is None:
                        break
                    self.wait(max(0, next_run - self.clock()))
                    continue
                ready = wait_connections(list(active), timeout=0.05)
                for connection in list(active):
                    process, job = active[connection]
                    timed_out = self.clock() >= job["deadline"]
                    if connection not in ready and not timed_out:
                        continue
                    if timed_out:
                        kind, payload = "failure", {"code": "attempt-timeout", "retryable": False}
                    else:
                        try:
                            kind, payload = connection.recv()
                        except EOFError:
                            kind, payload = "failure", {"code": "worker-exited", "retryable": True}
                    if process.is_alive() and timed_out:
                        process.terminate()
                    process.join(5)
                    if process.is_alive():
                        process.kill()
                        process.join()
                    connection.close()
                    del active[connection]
                    if kind == "result":
                        self.repository.finish(job, payload)
                        self.hook("completed", job)
                    else:
                        self._failure(job, payload)
        finally:
            for connection, (process, job) in active.items():
                process.terminate()
                process.join(5)
                if process.is_alive():
                    process.kill()
                    process.join()
                connection.close()
                self.repository.interrupt(job)
            if old_handler is not None:
                signal.signal(signal.SIGTERM, old_handler)
        return metrics

"""Read independent exports, keeping source identity separate from metadata."""

import hashlib
import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterable

from .providers import Provider


class InputError(ValueError):
    """An export or batch cannot be interpreted unambiguously."""


@dataclass(frozen=True)
class SourceDocument:
    document_id: str
    source_sha256: str
    source_bytes: bytes
    message: str


@dataclass(frozen=True)
class InputResult:
    document_id: str
    source_sha256: str
    message: str | None
    response: dict[str, Any] | None
    error: dict[str, str] | None


def decode_export(path: Path, raw: bytes) -> SourceDocument:
    """Hash original bytes and expose only the decoded message to extraction."""
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as error:
        raise InputError(
            f"{path.name}: invalid UTF-8 at byte {error.start}; re-export as UTF-8"
        ) from error
    try:
        export = json.loads(text)
    except json.JSONDecodeError as error:
        raise InputError(
            f"{path.name}: invalid JSON at line {error.lineno}, column {error.colno}; "
            "supply a valid JSON export"
        ) from error
    if not isinstance(export, dict):
        raise InputError(f"{path.name}: export must be a JSON object containing a message string")
    if not isinstance(export.get("message"), str):
        raise InputError(f"{path.name}: message is missing or is not a string; supply message text")
    return SourceDocument(
        document_id=path.name,
        source_sha256=hashlib.sha256(raw).hexdigest(),
        source_bytes=raw,
        message=export["message"],
    )


def process_exports(paths: Iterable[Path], *, provider: Provider) -> list[InputResult]:
    """Reject duplicate basenames before calls; isolate malformed input errors."""
    batch = [Path(path) for path in paths]
    seen: set[str] = set()
    for path in batch:
        if path.name in seen:
            raise InputError(f"Duplicate basename {path.name}; use distinct filenames in a batch")
        seen.add(path.name)

    results = []
    for path in batch:
        raw = path.read_bytes()
        try:
            document = decode_export(path, raw)
        except InputError as error:
            results.append(InputResult(
                document_id=path.name,
                source_sha256=hashlib.sha256(raw).hexdigest(),
                message=None,
                response=None,
                error={"code": "input-error", "message": str(error)},
            ))
            continue
        results.append(InputResult(
            document_id=document.document_id,
            source_sha256=document.source_sha256,
            message=document.message,
            response=provider.extract(document.message),
            error=None,
        ))
    return results

