"""Bounded POSIX workers, durable backoff and total-attempt deadlines."""

import json
import math
import multiprocessing
import random
import signal
import threading
from multiprocessing.connection import wait as wait_connections
from time import sleep

from .http_provider import ProviderFailure
from .inputs import InputError, decode_export
from .repository import ProcessingSettings, Repository
from .providers import ProviderUnavailable
from .validation import error_record


def retry_delay(error, calls, *, jitter=random.random, base_delay=0.5):
    requested = getattr(error, "retry_after", None)
    if requested is not None and math.isfinite(requested):
        return min(60, max(0, requested))
    base = min(10, base_delay * 2 ** max(0, calls - 1))
    return min(10, base * (1 + min(1, max(0, jitter())) * 0.25))


def _compute(path, job, provider, sender, remaining):
    signal.signal(signal.SIGTERM, signal.SIG_DFL)
    signal.signal(signal.SIGINT, signal.SIG_IGN)
    signal.signal(signal.SIGALRM, signal.SIG_DFL)
    signal.setitimer(signal.ITIMER_REAL, remaining)
    try:
        with Repository(path) as repo:
            result = repo.compute(job, provider=provider, raise_provider_errors=True, call_recorded=True)
        sender.send(("result", result))
    except (ProviderUnavailable, TimeoutError) as error:
        sender.send(("failure", {
            "code": getattr(error, "code", "provider-timeout" if isinstance(error, TimeoutError) else "provider-unavailable"),
            "retryable": getattr(error, "retryable", True), "retry_after": getattr(error, "retry_after", None),
        }))
    except BaseException:
        sender.send(("failure", {"code": "worker-error", "retryable": False}))
    finally:
        sender.close()


class Scheduler:
    def __init__(self, repository, *, provider_factory, workers=4, timeout=60, max_calls=3,
                 clock=None, wait=sleep, jitter=random.random, base_delay=0.5, hook=None):
        if (not 1 <= workers <= 32 or not math.isfinite(timeout) or timeout <= 0
                or not 1 <= max_calls <= 3 or not math.isfinite(base_delay) or base_delay < 0):
            raise ValueError("Use 1–32 workers, a positive finite timeout, 1–3 calls and nonnegative backoff")
        if "fork" not in multiprocessing.get_all_start_methods():
            raise ValueError("The worker scheduler requires a POSIX host with fork")
        self.context = multiprocessing.get_context("fork")
        self.repository, self.factory = repository, provider_factory
        self.workers, self.timeout, self.max_calls = workers, timeout, max_calls
        self.clock, self.wait, self.jitter = clock or repository.clock, wait, jitter
        self.base_delay = base_delay
        self.hook = hook or (lambda stage, job: None)

    @staticmethod
    def _needs_provider(job):
        if job["kind"] != "extract":
            return False
        try:
            decode_export(__import__("pathlib").Path(job["document_id"]), job["source_bytes"])
        except InputError:
            return False
        return True

    def _failure(self, job, details):
        error = ProviderFailure(details["code"], "Provider call failed", retryable=details["retryable"],
                                retry_after=details.get("retry_after"))
        if error.retryable and job["call_count"] < self.max_calls:
            delay = retry_delay(error, job["call_count"], jitter=self.jitter, base_delay=self.base_delay)
            if self.clock() + delay < job["deadline"] and self.repository.defer(job, seconds=delay, code=error.code):
                self.hook("retry-wait", job)
                return
        settings = ProcessingSettings(**json.loads(job["settings_json"]))
        origin = "mock" if settings.provider == "mock" else f"{settings.provider}/{settings.model}"
        result = self.repository.decorate(job, error_record(error.code, "Extraction failed or timed out; retry this saved attempt", origin))
        self.repository.finish(job, result)
        self.hook("completed", job)

    @staticmethod
    def _stop(process, *, terminate=False):
        if process.pid is None:
            return
        if terminate and process.is_alive():
            process.terminate()
        process.join(0.5)
        if process.is_alive():
            process.kill()
            process.join(1)

    def run(self):
        self.repository.recover()
        active, pending_claim = {}, None
        metrics = {"max_active": 0, "calls": 0}
        old_handler = None
        if threading.current_thread() is threading.main_thread():
            old_handler = signal.getsignal(signal.SIGTERM)
            def interrupted(signum, frame):
                raise KeyboardInterrupt
            signal.signal(signal.SIGTERM, interrupted)
        try:
            while True:
                while len(active) < self.workers:
                    job = self.repository.claim(lease_seconds=self.timeout + 5)
                    if job is None:
                        break
                    pending_claim = job
                    needs_provider = self._needs_provider(job)
                    exhausted = needs_provider and job["call_count"] >= self.max_calls
                    expired = job["deadline"] is not None and self.clock() >= job["deadline"]
                    provider = None
                    configuration_failed = False
                    if needs_provider and not exhausted and not expired:
                        try:
                            provider = self.factory(ProcessingSettings(**json.loads(job["settings_json"])))
                        except (ValueError, OSError, KeyError, ProviderUnavailable):
                            configuration_failed = True
                    job = self.repository.prepare_execution(job, timeout=self.timeout,
                        call_provider=needs_provider and not (exhausted or expired or configuration_failed))
                    pending_claim = job
                    if self.clock() >= job["deadline"] or exhausted or configuration_failed:
                        code = ("attempt-timeout" if self.clock() >= job["deadline"] else
                                "provider-configuration" if configuration_failed else job["last_error_code"] or "retry-limit")
                        self._failure(job, {"code": code, "retryable": False})
                        pending_claim = None
                        continue
                    receiver, sender = self.context.Pipe(duplex=False)
                    process = self.context.Process(target=_compute,
                        args=(self.repository.path, job, provider, sender, max(0.001, job["deadline"] - self.clock())))
                    active[receiver] = (process, job)
                    pending_claim = None
                    try:
                        process.start()
                    finally:
                        sender.close()
                    metrics["calls"] += int(needs_provider)
                    metrics["max_active"] = max(metrics["max_active"], len(active))
                    self.hook("spawned", job)
                if not active:
                    ready_at = self.repository.next_ready_at()
                    if ready_at is None:
                        break
                    self.wait(max(0, ready_at - self.clock()))
                    continue
                ready = wait_connections(list(active), timeout=0.05)
                for connection in list(active):
                    process, job = active[connection]
                    expired = self.clock() >= job["deadline"]
                    if connection not in ready and not expired:
                        continue
                    if expired:
                        kind, payload = "failure", {"code": "attempt-timeout", "retryable": False}
                    else:
                        try:
                            kind, payload = connection.recv()
                        except (EOFError, OSError):
                            kind, payload = "failure", {"code": "worker-exited", "retryable": True}
                    self._stop(process, terminate=expired)
                    if process.exitcode == -signal.SIGALRM:
                        kind, payload = "failure", {"code": "attempt-timeout", "retryable": False}
                    connection.close()
                    del active[connection]
                    if kind == "result":
                        self.repository.finish(job, payload)
                        self.hook("completed", job)
                    else:
                        self._failure(job, payload)
        finally:
            for connection, (process, job) in active.items():
                self._stop(process, terminate=True)
                connection.close()
                self.repository.interrupt(job)
            if pending_claim is not None:
                self.repository.interrupt(pending_claim)
            if old_handler is not None:
                signal.signal(signal.SIGTERM, old_handler)
        return metrics

"""JSON operator commands over a shared, explicitly selected state database."""

import argparse
import json
import math
import sqlite3
import sys
from dataclasses import replace
from pathlib import Path

from .inputs import batch_paths
from .mock_config import DEFAULT_MOCK_MAP, MockConfiguration, provider_for_settings
from .policy import POLICY_VERSION
from .prompt import PROMPT_VERSION, SYSTEM_PROMPT
from .repository import ProcessingSettings, Repository
from .scheduler import Scheduler
from .validation import SCHEMA


def _parser():
    parser = argparse.ArgumentParser(prog="python3 -m access_intake")
    commands = parser.add_subparsers(dest="command", required=True)
    for name in ("intake", "queue", "progress", "history", "retry", "resume", "refresh", "export"):
        command = commands.add_parser(name)
        command.add_argument("--state", type=Path, required=True)
        if name in ("intake", "refresh"):
            command.add_argument("--provider", choices=("mock", "live"), default="mock" if name == "intake" else None)
            command.add_argument("--mock-map", type=Path)
            command.add_argument("--policy-version")
            command.add_argument("--prompt-file", type=Path)
        if name == "intake":
            command.add_argument("paths", nargs="+", type=Path)
        if name in ("intake", "retry", "resume", "refresh"):
            command.add_argument("--workers", type=int, default=4)
            command.add_argument("--timeout", type=float, default=60)
            command.add_argument("--max-calls", type=int, default=3)
            command.add_argument("--enqueue-only", action="store_true")
        if name in ("queue", "progress", "history"):
            command.add_argument("--limit", type=int, default=100)
            command.add_argument("--offset", type=int, default=0)
        if name == "history":
            command.add_argument("--document", required=True)
        if name == "retry":
            command.add_argument("--attempt", required=True)
        if name == "export":
            command.add_argument("--out", type=Path, required=True)
    return parser


def _settings(args):
    if args.provider == "live":
        from .http_provider import HttpProvider
        settings = ProcessingSettings.from_provider(HttpProvider.from_environment())
    else:
        settings = ProcessingSettings()
    if args.policy_version is not None:
        settings = replace(settings, policy_version=args.policy_version)
    if args.prompt_file is not None:
        settings = replace(settings, prompt=args.prompt_file.read_text(encoding="utf-8"))
    return settings


def _refresh(repo, args):
    explicit = _settings(args) if args.provider is not None or args.mock_map is not None else None
    mapping = MockConfiguration(args.mock_map or DEFAULT_MOCK_MAP) if args.mock_map or args.provider == "mock" else None
    prompt = args.prompt_file.read_text(encoding="utf-8") if args.prompt_file else None
    after = ""
    while True:
        rows = repo.latest_inputs(after_document=after)
        if not rows:
            break
        for row in rows:
            settings = explicit or ProcessingSettings(**row["settings"])
            if explicit is None and args.policy_version is None and prompt is None:
                settings = replace(settings, prompt=SYSTEM_PROMPT, schema=SCHEMA,
                                   extraction_version=PROMPT_VERSION, REDACTED)
            if args.policy_version is not None:
                settings = replace(settings, policy_version=args.policy_version)
            if prompt is not None:
                settings = replace(settings, prompt=prompt)
            if mapping is not None:
                if settings.provider != "mock":
                    raise ValueError("--mock-map requires a mock provider")
                settings = mapping.settings_for(row["document_id"], row["source_bytes"], settings)
            repo.schedule_source(row["document_id"], row["source_bytes"], settings=settings,
                                 expected_latest=row["attempt_id"])
        after = rows[-1]["document_id"]


def main(argv=None, *, provider_factory=None, hook=None, scheduler_options=None):
    args = _parser().parse_args(argv)
    try:
        if hasattr(args, "limit") and (not 1 <= args.limit <= 1000 or args.offset < 0):
            raise ValueError("Use --limit 1–1000 and a nonnegative --offset")
        if hasattr(args, "workers") and (not 1 <= args.workers <= 32 or not math.isfinite(args.timeout)
                                         or args.timeout <= 0 or not 1 <= args.max_calls <= 3):
            raise ValueError("Use 1–32 workers, a finite positive timeout and 1–3 provider calls")
        if args.command != "intake" and not args.state.is_file():
            raise ValueError("State database does not exist; select the intake state path")
        with Repository(args.state) as repo:
            if args.command == "queue":
                result = repo.queue_page(limit=args.limit, offset=args.offset)
            elif args.command == "progress":
                result = repo.progress_page(limit=args.limit, offset=args.offset)
            elif args.command == "history":
                result = repo.history_page(args.document, limit=args.limit, offset=args.offset)
            elif args.command == "export":
                from .snapshots import export_generation
                result = export_generation(repo, args.out)
            else:
                if args.command == "intake":
                    paths = batch_paths(p for path in args.paths for p in (sorted(path.glob("*.json")) if path.is_dir() else [path]))
                    if not paths:
                        raise ValueError("No JSON exports found in the selected input")
                    settings = _settings(args)
                    mapping = MockConfiguration(args.mock_map or DEFAULT_MOCK_MAP) if args.provider == "mock" else None
                    for path in paths:
                        raw = path.read_bytes()
                        producing = mapping.settings_for(path, raw, settings) if mapping is not None else settings
                        repo.schedule_source(path.name, raw, settings=producing)
                elif args.command == "retry":
                    repo.enqueue_retry(args.attempt)
                elif args.command == "refresh":
                    _refresh(repo, args)
                metrics = {"calls": 0, "max_active": 0}
                if not args.enqueue_only:
                    metrics = Scheduler(repo, provider_factory=provider_factory or provider_for_settings,
                                        workers=args.workers, timeout=args.timeout, max_calls=args.max_calls,
                                        hook=hook, **(scheduler_options or {})).run()
                result = {"scheduler": metrics, "progress": repo.progress_page(limit=20)}
        print(json.dumps(result, ensure_ascii=False, allow_nan=False))
        return 0
    except KeyboardInterrupt:
        return 130
    except (ValueError, OSError, KeyError, sqlite3.Error) as error:
        print(json.dumps({"error": str(error)}, ensure_ascii=False), file=sys.stderr)
        return 2

"""Explicit saved-envelope configuration for offline operator commands."""

import copy
import hashlib
import json
from dataclasses import replace
from pathlib import Path

from .http_provider import HttpProvider, ProviderFailure
from .inputs import InputError, decode_export


DEFAULT_MOCK_MAP = Path(__file__).resolve().parents[1] / "config" / "mock-map.json"
MAX_MOCK_BYTES = 1_048_576


class MockConfiguration:
    def __init__(self, path):
        self.path = Path(path).resolve()
        self.entries = json.loads(self.path.read_text(encoding="utf-8"))
        if not isinstance(self.entries, dict):
            raise ValueError("Mock map must be an object keyed by decoded-message SHA-256")
        self._fixtures = {}

    def settings_for(self, path, raw, settings):
        try:
            source = decode_export(Path(path), raw)
        except InputError:
            return settings
        entry = self.entries.get(hashlib.sha256(source.message.encode("utf-8")).hexdigest())
        if entry is None:
            return replace(settings, request_settings={})
        if not isinstance(entry, dict) or not isinstance(entry.get("response"), str):
            raise ValueError("Each mock-map entry needs a response filename")
        substitutions = entry.get("substitutions", {})
        if not isinstance(substitutions, dict) or any(not isinstance(k, str) or not k or not isinstance(v, str) for k, v in substitutions.items()):
            raise ValueError("Mock substitutions must map nonempty strings to strings")
        fixture = (self.path.parent / entry["response"]).resolve()
        if fixture not in self._fixtures:
            with fixture.open("rb") as reply:
                contents = reply.read(MAX_MOCK_BYTES + 1)
            if len(contents) > MAX_MOCK_BYTES:
                raise ValueError("Saved mock response exceeds the 1 MiB limit")
            self._fixtures[fixture] = {"path": str(fixture), "sha256": hashlib.sha256(contents).hexdigest()}
        return replace(settings, request_settings={"mock_response": {
            **self._fixtures[fixture], "substitutions": dict(substitutions),
        }})


class SavedProvider:
    response_source = "mock"

    def __init__(self, settings):
        self.settings = settings

    def processing_configuration(self):
        return {
            "provider": self.settings.provider, "model": self.settings.model,
            "endpoint": self.settings.endpoint, "request_settings": copy.deepcopy(self.settings.request_settings),
            "prompt": self.settings.prompt, "schema": copy.deepcopy(self.settings.schema),
        }

    def extract(self, message):
        entry = self.settings.request_settings.get("mock_response")
        try:
            if not entry:
                raise ValueError("No saved reply")
            with Path(entry["path"]).open("rb") as reply:
                raw = reply.read(MAX_MOCK_BYTES + 1)
            if len(raw) > MAX_MOCK_BYTES or hashlib.sha256(raw).hexdigest() != entry["sha256"]:
                raise ValueError("Saved reply changed")
            text = raw.decode("utf-8")
            for old, new in entry.get("substitutions", {}).items():
                text = text.replace(old, new)
            if len(text.encode("utf-8")) > MAX_MOCK_BYTES:
                raise ValueError("Expanded reply too large")
            envelope = json.loads(text)
            if not isinstance(envelope, dict):
                raise ValueError("Saved reply must be an envelope object")
        except (OSError, ValueError, KeyError, TypeError):
            raise ProviderFailure("mock-response", "Saved mock reply is missing, changed or invalid; refresh with a valid --mock-map") from None
        return {**envelope, "response_source": "mock"}


def provider_for_settings(settings):
    if settings.provider == "mock":
        return SavedProvider(settings)
    return HttpProvider.from_settings(settings)
